SELECT p1.c1 AS result
FROM (
    SELECT JSON_SCALAR((SELECT REGEXP_REPLACE(LTRIM(TO_CHAR(sh2.v1, 'SYYYY-MM-DD')), '^-[0-9]{4}', TO_CHAR(EXTRACT(YEAR FROM sh2.v1) + 1, 'FM0000')) FROM (SELECT /*+ NO_MERGE */ ((SELECT (CAST(ADD_MONTHS(TRUNC(CAST(sh1.v1 AS DATE), 'MM'), sh1.v2) AS TIMESTAMP) + NUMTODSINTERVAL(LEAST(EXTRACT(DAY FROM sh1.v1), EXTRACT(DAY FROM LAST_DAY(ADD_MONTHS(TRUNC(CAST(sh1.v1 AS DATE), 'MM'), sh1.v2)))) - 1, 'DAY') + (sh1.v1 - CAST(TRUNC(CAST(sh1.v1 AS DATE)) AS TIMESTAMP))) FROM (SELECT /*+ NO_MERGE */ TO_TIMESTAMP(CASE WHEN ASCII('-0044-03-15') < 49 THEN REGEXP_REPLACE('-0044-03-15', '^(-[0-9]{4}|0000)', TO_CHAR(TO_NUMBER(REGEXP_SUBSTR('-0044-03-15', '^-?[0-9]{4}')) - 1, 'FM0000')) ELSE '-0044-03-15' END, 'SYYYY-MM-DD') AS v1, (TO_NUMBER('0')) AS v2) sh1) + NUMTODSINTERVAL((TO_NUMBER('1')), 'DAY') + NUMTODSINTERVAL((CASE WHEN 1 = 1 THEN TRUNC(TO_NUMBER('0') / 86400) * 86400 ELSE TO_NUMBER('0') END), 'SECOND')) AS v1) sh2)) AS c1
) p1